import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a shifted Rosenbrock-like term with a skewed polynomial.

    This function attempts to mimic the specified ELA features by incorporating nonlinearity, skewness, and controlled interactions.

    Formula:
    f(x) = 0.5*(1 - (x[0] + 1))**2 + 50 * ((x[1] - (x[0] + 1)**2)**2) + 0.005 * (x[0]**3 + x[1]**3) + 0.2*x[0]*x[1] + 0.4*(x[0] + x[1]) + 0.01*(x[0]**2 + x[1]**2)
           return 0.02 * (0.5*(1 - (x[0] + 1))**2 + 50 * ((x[1] - (x[0] + 1)**2)**2) + 0.005 * (x[0]**3 + x[1]**3) + 0.2*x[0]*x[1] + 0.4*(x[0] + x[1]) + 0.01*(x[0]**2 + x[1]**2))
    """
    return 0.02 * (0.5*(1 - (x[0] + 1))**2 + 50 * ((x[1] - (x[0] + 1)**2)**2) + 0.005 * (x[0]**3 + x[1]**3) + 0.2*x[0]*x[1] + 0.4*(x[0] + x[1]) + 0.01*(x[0]**2 + x[1]**2))
